/* Integer lists: the exact sum, and the first index of the extreme. */
static inline faber_i128 faber_list_i64_sum(const faber_list_i64 *list) {
    faber_i128 total = 0;
    int64_t at;
    for (at = 0; at < list->len; at++) {
        total = faber_add(total, list->items[at]);
    }
    return total;
}

static inline bool faber_list_i64_argmax(const faber_list_i64 *list, int64_t *out) {
    int64_t at;
    if (list->len == 0) {
        return false;
    }
    *out = 0;
    for (at = 1; at < list->len; at++) {
        if (list->items[at] > list->items[*out]) {
            *out = at;
        }
    }
    return true;
}

static inline bool faber_list_i64_argmin(const faber_list_i64 *list, int64_t *out) {
    int64_t at;
    if (list->len == 0) {
        return false;
    }
    *out = 0;
    for (at = 1; at < list->len; at++) {
        if (list->items[at] < list->items[*out]) {
            *out = at;
        }
    }
    return true;
}

/* ------------------------------------------------------------------------ */
/* Text operations: UTF-8, counted in code points as the runner counts      */
/* ------------------------------------------------------------------------ */

/* The byte length of the code point that starts at `p`, never past the
 * terminator (argument text need not be valid UTF-8). */
static inline size_t faber_utf8_step(const unsigned char *p) {
    size_t want = p[0] < 0x80 ? 1 : p[0] >= 0xF0 ? 4 : p[0] >= 0xE0 ? 3 : 2;
    size_t have = 1;
    while (have < want && p[have] != 0) {
        have++;
    }
    return have;
}

static inline uint32_t faber_utf8_decode(const unsigned char *p, size_t length) {
    uint32_t cp;
    switch (length) {
    case 1:
        return p[0];
    case 2:
        cp = (uint32_t)(p[0] & 0x1F) << 6;
        return cp | (uint32_t)(p[1] & 0x3F);
    case 3:
        cp = (uint32_t)(p[0] & 0x0F) << 12;
        cp |= (uint32_t)(p[1] & 0x3F) << 6;
        return cp | (uint32_t)(p[2] & 0x3F);
    default:
        cp = (uint32_t)(p[0] & 0x07) << 18;
        cp |= (uint32_t)(p[1] & 0x3F) << 12;
        cp |= (uint32_t)(p[2] & 0x3F) << 6;
        return cp | (uint32_t)(p[3] & 0x3F);
    }
}

static inline faber_text faber_text_copy(faber_arena *arena, const char *from, size_t length) {
    return faber_text_make(arena, from, length, faber_text_count_cps(from, length));
}

static inline int64_t faber_text_length(faber_text text) {
    return faber_text_hdr(text)->cps;
}

/* The code points in `length` raw bytes: the walk `faber_text_length` used
 * to do, stopped at the given width (a fresh buffer or a prefix of a text,
 * so it never meets a NUL before the end). */
static inline int64_t faber_text_count_cps(const char *from, size_t length) {
    const unsigned char *p = (const unsigned char *)from;
    const unsigned char *end = p + length;
    int64_t count = 0;
    while (p < end) {
        p += faber_utf8_step(p);
        count++;
    }
    return count;
}

/* `textus ↦ string<N>`: the capacity is in code points and is checked at run
 * time (the typechecker proves a literal fits). Mirrors the runner's
 * bounded-text store. */
static inline faber_text faber_bounded_text(faber_text text, int64_t capacity) {
    if (faber_text_length(text) > capacity) {
        faber_trap("textus to bounded textus conversion failed");
    }
    return text;
}

/* `ascii<N> ↦ ascii<M>` (D7 resize): the text stays when it fits the new
 * capacity in code points, and the program ends otherwise. */
static inline faber_text faber_bounded_ascii(faber_text text, int64_t capacity) {
    if (faber_text_length(text) > capacity) {
        faber_trap("ascii to bounded ascii conversion failed");
    }
    return text;
}

/* `s.slice(from, to)`: code-point positions, clamped to the text, empty when
 * `from` is not before `to`; a negative position traps as the runner does. */
static inline faber_text faber_text_slice(faber_arena *arena, faber_text text, faber_i128 from,
                                          faber_i128 to) {
    const unsigned char *start = (const unsigned char *)text;
    const unsigned char *end;
    faber_i128 index = 0;
    if (from < 0 || to < 0) {
        faber_trap("expected non-negative numerus index");
    }
    if (from >= to) {
        return faber_text_empty.s;
    }
    while (*start != 0 && index < from) {
        start += faber_utf8_step(start);
        index++;
    }
    end = start;
    while (*end != 0 && index < to) {
        end += faber_utf8_step(end);
        index++;
    }
    return faber_text_make(arena, (const char *)start, (size_t)(end - start),
                           index > from ? (int64_t)(index - from) : 0);
}

/* `s[i]`: the code point at `index` as text. */
static inline faber_text faber_text_at(faber_arena *arena, faber_text text, faber_i128 index) {
    const unsigned char *p = (const unsigned char *)text;
    faber_i128 at = 0;
    if (index < 0) {
        faber_trap("expected non-negative numerus index");
    }
    while (*p != 0 && at < index) {
        p += faber_utf8_step(p);
        at++;
    }
    if (*p == 0) {
        faber_trap("text index out of bounds");
    }
    {
        size_t step = faber_utf8_step(p);
        return faber_text_make(arena, (const char *)p, step, 1);
    }
}

static inline bool faber_text_contains(faber_text text, faber_text needle) {
    return strstr(text, needle) != NULL;
}

static inline bool faber_text_starts_with(faber_text text, faber_text prefix) {
    size_t prefix_length = (size_t)faber_text_hdr(prefix)->bytes;
    return strncmp(text, prefix, prefix_length) == 0;
}

static inline bool faber_text_ends_with(faber_text text, faber_text suffix) {
    size_t text_length = (size_t)faber_text_hdr(text)->bytes;
    size_t suffix_length = (size_t)faber_text_hdr(suffix)->bytes;
    return suffix_length <= text_length &&
           memcmp(text + text_length - suffix_length, suffix, suffix_length) == 0;
}

/* Case mapping is ASCII only: a byte outside ASCII would need the Unicode
 * tables, so it stops the program rather than answer differently from the
 * runner. */
static inline faber_text faber_text_case(faber_arena *arena, faber_text text, bool upper) {
    size_t length = (size_t)faber_text_hdr(text)->bytes;
    char *buffer = faber_alloc(arena, sizeof(faber_text_header) + length + 1);
    char *out = buffer + sizeof(faber_text_header);
    size_t index;
    for (index = 0; index < length; index++) {
        unsigned char c = (unsigned char)text[index];
        if (c >= 0x80) {
            faber_abort("unsupported on target c: case mapping of non-ASCII text");
        }
        if (upper && c >= 'a' && c <= 'z') {
            c = (unsigned char)(c - 'a' + 'A');
        } else if (!upper && c >= 'A' && c <= 'Z') {
            c = (unsigned char)(c - 'A' + 'a');
        }
        out[index] = (char)c;
    }
    out[length] = '\0';
    return faber_text_seal(buffer, length, (int64_t)length);
}

/* Unicode White_Space, which `trim` strips from both ends. */
static inline bool faber_is_space(uint32_t cp) {
    return (cp >= 0x09 && cp <= 0x0D) || cp == 0x20 || cp == 0x85 || cp == 0xA0 ||
           cp == 0x1680 || (cp >= 0x2000 && cp <= 0x200A) || cp == 0x2028 || cp == 0x2029 ||
           cp == 0x202F || cp == 0x205F || cp == 0x3000;
}

static inline faber_text faber_text_trim(faber_arena *arena, faber_text text) {
    const unsigned char *start = (const unsigned char *)text;
    const unsigned char *end = start + strlen(text);
    while (*start != 0) {
        size_t step = faber_utf8_step(start);
        if (!faber_is_space(faber_utf8_decode(start, step))) {
            break;
        }
        start += step;
    }
    while (end > start) {
        const unsigned char *lead = end - 1;
        while (lead > start && (*lead & 0xC0) == 0x80) {
            lead--;
        }
        if (!faber_is_space(faber_utf8_decode(lead, (size_t)(end - lead)))) {
            break;
        }
        end = lead;
    }
    return faber_text_copy(arena, (const char *)start, (size_t)(end - start));
}

/* `s.split(sep)`, as Rust's `str::split`: an empty separator splits around
 * every code point, with an empty piece at each end. */
static inline faber_list_text *faber_text_split(faber_arena *arena, faber_text text,
                                                faber_text separator) {
    faber_list_text *list = faber_list_text_new(arena, 0);
    size_t separator_length = strlen(separator);
    const char *cursor = text;
    if (separator_length == 0) {
        const unsigned char *p = (const unsigned char *)text;
        faber_list_text_push(arena, list, faber_text_empty.s);
        while (*p != 0) {
            size_t step = faber_utf8_step(p);
            faber_list_text_push(arena, list, faber_text_copy(arena, (const char *)p, step));
            p += step;
        }
        faber_list_text_push(arena, list, faber_text_empty.s);
        return list;
    }
    for (;;) {
        const char *hit = strstr(cursor, separator);
        if (hit == NULL) {
            faber_list_text_push(arena, list, faber_text_copy(arena, cursor, strlen(cursor)));
            return list;
        }
        faber_list_text_push(arena, list, faber_text_copy(arena, cursor, (size_t)(hit - cursor)));
        cursor = hit + separator_length;
    }
}

/* `s.replace(from, to)`, as Rust's `str::replace`: an empty `from` matches
 * before every code point and at the end. */
static inline faber_text faber_text_replace(faber_arena *arena, faber_text text, faber_text from,
                                            faber_text to) {
    size_t from_length = strlen(from);
    size_t to_length = strlen(to);
    size_t text_length = strlen(text);
    size_t matches = 0;
    char *out;
    char *cursor;
    if (from_length == 0) {
        matches = (size_t)faber_text_length(text) + 1;
        out = faber_alloc(arena, sizeof(faber_text_header) + text_length + matches * to_length + 1);
        cursor = out + sizeof(faber_text_header);
        for (const unsigned char *p = (const unsigned char *)text;; p += faber_utf8_step(p)) {
            memcpy(cursor, to, to_length);
            cursor += to_length;
            if (*p == 0) {
                break;
            }
            memcpy(cursor, p, faber_utf8_step(p));
            cursor += faber_utf8_step(p);
        }
        *cursor = '\0';
        return faber_text_seal(out, (size_t)(cursor - out - sizeof(faber_text_header)),
                               faber_text_count_cps(out + sizeof(faber_text_header),
                                                    (size_t)(cursor - out -
                                                             sizeof(faber_text_header))));
    }
    for (const char *scan = strstr(text, from); scan != NULL; scan = strstr(scan + from_length, from)) {
        matches++;
    }
    out = faber_alloc(arena, sizeof(faber_text_header) + text_length + matches * to_length + 1);
    out[0] = '\0';
    cursor = out + sizeof(faber_text_header);
    for (const char *rest = text;;) {
        const char *hit = strstr(rest, from);
        if (hit == NULL) {
            size_t tail = strlen(rest);
            memcpy(cursor, rest, tail);
            cursor += tail;
            break;
        }
        memcpy(cursor, rest, (size_t)(hit - rest));
        cursor += hit - rest;
        memcpy(cursor, to, to_length);
        cursor += to_length;
        rest = hit + from_length;
    }
    *cursor = '\0';
    return faber_text_seal(out, (size_t)(cursor - out - sizeof(faber_text_header)),
                           faber_text_count_cps(out + sizeof(faber_text_header),
                                                (size_t)(cursor - out -
                                                         sizeof(faber_text_header))));
}

/* ------------------------------------------------------------------------ */
/* Conversions (`↦`): each "try" reports 0 or why it failed; the program    */
/* either recovers (`⊥`) or ends with the runner's text for that failure    */
/* ------------------------------------------------------------------------ */

enum {
    FABER_CONV_OK = 0,
    FABER_CONV_SYNTAX = 1, /* the text is not a number */
    FABER_CONV_RANGE = 2,  /* a number, but outside the target */
    FABER_CONV_NEGATIVE = 3 /* a negative source where only magnitude is taken */
};

enum {
    FABER_CONV_TEXT_INT = 0,
    FABER_CONV_TEXT_FLOAT = 1,
    FABER_CONV_INT_INT = 2,
    FABER_CONV_FLOAT_INT = 3,
    FABER_CONV_TEXT_BOOL = 4,
    FABER_CONV_ASCII_PACK = 5,
    FABER_CONV_BYTES_TEXT = 6
};

static inline _Noreturn void faber_conv_fail(int kind, int why) {
    switch (kind) {
    case FABER_CONV_TEXT_INT:
        faber_trap(why == FABER_CONV_SYNTAX ? "textus to numerus conversion failed"
                                            : "textus to numerus conversion out of range");
    case FABER_CONV_TEXT_FLOAT:
        faber_trap("textus to fractus conversion failed");
    case FABER_CONV_TEXT_BOOL:
        faber_trap("text to bivalens conversion failed");
    case FABER_CONV_ASCII_PACK:
        faber_trap(why == FABER_CONV_NEGATIVE ? "ascii_pack_negative_source"
                                              : "ascii_pack_width_overflow");
    case FABER_CONV_BYTES_TEXT:
        faber_trap("list<b8> to textus conversion failed");
    case FABER_CONV_INT_INT:
        faber_trap("numerus to numerus conversion out of range");
    default:
        faber_trap("fractus to numerus conversion out of range");
    }
}

/* `numerus ↦ ascii<N> via Hex|Bin|Oct`: the zero-padded fixed-width digits
 * in `arena`. Returns NULL when the value is negative or its digits do not
 * fit `width`, with `*why` set to the runner's code; the caller traps or
 * takes the `⊥` fallback. */
static inline faber_text faber_try_ascii_pack(faber_arena *arena, faber_i128 value, int radix,
                                              int64_t width, int *why) {
    static const char alphabet[] = "0123456789abcdef";
    char reversed[72];
    size_t count = 0;
    uint64_t magnitude;
    char *out;
    size_t at;
    if (value < 0) {
        *why = FABER_CONV_NEGATIVE;
        return NULL;
    }
    magnitude = (uint64_t)value;
    if (magnitude == 0) {
        reversed[count++] = '0';
    }
    while (magnitude > 0) {
        reversed[count++] = alphabet[magnitude % (uint64_t)radix];
        magnitude /= (uint64_t)radix;
    }
    if ((int64_t)count > width) {
        *why = FABER_CONV_RANGE;
        return NULL;
    }
    *why = FABER_CONV_OK;
    out = faber_alloc(arena, sizeof(faber_text_header) + (size_t)width + 1);
    {
        char *digits = out + sizeof(faber_text_header);
        for (at = 0; at < (size_t)width - count; at++) {
            digits[at] = '0';
        }
        for (at = 0; at < count; at++) {
            digits[width - 1 - (int64_t)at] = reversed[at];
        }
        digits[width] = '\0';
    }
    return faber_text_seal(out, (size_t)width, width);
}

/* `numerus ↦ numerus` into a width: in range or not. */
static inline int faber_try_int(faber_i128 value, faber_i128 low, faber_i128 high,
                                faber_i128 *out) {
    *out = value;
    return value >= low && value <= high ? FABER_CONV_OK : FABER_CONV_RANGE;
}

/* `textus ↦ numerus [via Hex|Bin|Oct]`: an optional sign, then digits of the
 * radix and nothing else. A run of digits past the exact range is a number
 * outside every width. */
static inline int faber_try_text_int(faber_text text, int radix, faber_i128 low, faber_i128 high,
                                     faber_i128 *out) {
    const char *p = text;
    bool negative = false;
    faber_i128 value = 0;
    const faber_i128 saturated = (faber_i128)1 << 100;
    if (*p == '+' || *p == '-') {
        negative = *p == '-';
        p++;
    }
    if (*p == '\0') {
        return FABER_CONV_SYNTAX;
    }
    for (; *p != '\0'; p++) {
        int digit;
        if (*p >= '0' && *p <= '9') {
            digit = *p - '0';
        } else if (*p >= 'a' && *p <= 'z') {
            digit = *p - 'a' + 10;
        } else if (*p >= 'A' && *p <= 'Z') {
            digit = *p - 'A' + 10;
        } else {
            return FABER_CONV_SYNTAX;
        }
        if (digit >= radix) {
            return FABER_CONV_SYNTAX;
        }
        if (value < saturated) {
            value = value * radix + digit;
        }
    }
    *out = negative ? -value : value;
    return *out >= low && *out <= high ? FABER_CONV_OK : FABER_CONV_RANGE;
}

/* Whether `length` bytes are one well-formed UTF-8 text: no overlong form,
 * no surrogate, nothing past U+10FFFF, and no `0x00` byte. The text carrier
 * is NUL-terminated, so a zero byte has no text value at all. */
static inline bool faber_utf8_well_formed(const unsigned char *source, size_t length) {
    size_t at = 0;
    while (at < length) {
        unsigned char lead = source[at];
        size_t width = 1;
        uint32_t least = 0;
        uint32_t cp;
        size_t step;
        if (lead == 0x00) {
            return false;
        }
        if (lead >= 0x80) {
            if (lead >= 0xC2 && lead <= 0xDF) {
                width = 2;
                least = 0x80;
            } else if (lead >= 0xE0 && lead <= 0xEF) {
                width = 3;
                least = 0x800;
            } else if (lead >= 0xF0 && lead <= 0xF4) {
                width = 4;
                least = 0x10000;
            } else {
                return false;
            }
            if (length - at < width) {
                return false;
            }
            for (step = 1; step < width; step++) {
                if ((source[at + step] & 0xC0) != 0x80) {
                    return false;
                }
            }
            cp = faber_utf8_decode(source + at, width);
            if (cp < least || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
                return false;
            }
        }
        at += width;
    }
    return true;
}

/* `lista<b8> ↦ string`: the UTF-8 decode, sealing the very bytes the list
 * holds. An ill-formed sequence fails, and so does any `0x00` byte: the
 * carrier has no text value for it, so the conversion fails exactly like a
 * bad sequence rather than truncating the text. `*why` is FABER_CONV_RANGE on
 * failure and the caller either traps or takes the `⊥` fallback. */
static inline faber_text faber_try_bytes_text(faber_arena *arena, const faber_list_b8 *bytes,
                                              int *why) {
    size_t length = (size_t)bytes->len;
    char *buffer;
    char *text;
    if (!faber_utf8_well_formed(bytes->items, length)) {
        *why = FABER_CONV_RANGE;
        return NULL;
    }
    *why = FABER_CONV_OK;
    buffer = faber_alloc(arena, sizeof(faber_text_header) + length + 1);
    text = buffer + sizeof(faber_text_header);
    if (length > 0) {
        memcpy(text, bytes->items, length);
    }
    text[length] = '\0';
    return faber_text_seal(buffer, length, faber_text_count_cps(text, length));
}

/* `string ↦ lista<b8>`: the UTF-8 encode, the header's byte count copied out.
 * It cannot fail: a text never carries a NUL byte. */
static inline faber_list_b8 *faber_text_bytes(faber_arena *arena, faber_text text) {
    size_t length = (size_t)faber_text_hdr(text)->bytes;
    faber_list_b8 *bytes = faber_list_b8_new(arena, (int64_t)length);
    if (length > 0) {
        memcpy(bytes->items, text, length);
    }
    bytes->len = (int64_t)length;
    return bytes;
}

static inline bool faber_ascii_equal_nocase(const char *a, const char *b) {
    for (; *a != '\0' && *b != '\0'; a++, b++) {
        char x = *a >= 'A' && *a <= 'Z' ? (char)(*a - 'A' + 'a') : *a;
        if (x != *b) {
            return false;
        }
    }
    return *a == '\0' && *b == '\0';
}

/* `textus ↦ fractus`, as Rust's `f64::from_str` reads it: an optional sign,
 * then `inf`, `infinity`, `nan` (any case) or decimal digits with an optional
 * point and exponent. No whitespace, no hex, no digit separators. */
static inline int faber_try_text_float(faber_text text, double *out) {
    const char *p = text;
    size_t digits = 0;
    if (*p == '+' || *p == '-') {
        p++;
    }
    if (faber_ascii_equal_nocase(p, "inf") || faber_ascii_equal_nocase(p, "infinity") ||
        faber_ascii_equal_nocase(p, "nan")) {
        *out = strtod(text, NULL);
        return FABER_CONV_OK;
    }
    while (*p >= '0' && *p <= '9') {
        p++;
        digits++;
    }
    if (*p == '.') {
        p++;
        while (*p >= '0' && *p <= '9') {
            p++;
            digits++;
        }
    }
    if (digits == 0) {
        return FABER_CONV_SYNTAX;
    }
    if (*p == 'e' || *p == 'E') {
        size_t exponent = 0;
        p++;
        if (*p == '+' || *p == '-') {
            p++;
        }
        while (*p >= '0' && *p <= '9') {
            p++;
            exponent++;
        }
        if (exponent == 0) {
            return FABER_CONV_SYNTAX;
        }
    }
    if (*p != '\0') {
        return FABER_CONV_SYNTAX;
    }
    *out = strtod(text, NULL);
    return FABER_CONV_OK;
}

/* `fractus ↦ numerus via <mode>`: 0 floor, 1 ceiling, 2 truncate, 3 nearest
 * with ties to the even neighbour. NaN and anything outside the cap fail. */
static inline int faber_try_float_int(double value, int mode, faber_i128 low, faber_i128 high,
                                      faber_i128 *out) {
    double rounded;
    if (value != value) {
        return FABER_CONV_RANGE;
    }
    switch (mode) {
    case 0:
        rounded = floor(value);
        break;
    case 1:
        rounded = ceil(value);
        break;
    case 2:
        rounded = trunc(value);
        break;
    default: {
        double below = floor(value);
        double gap = value - below;
        if (gap < 0.5) {
            rounded = below;
        } else if (gap > 0.5) {
            rounded = below + 1.0;
        } else {
            rounded = fmod(below, 2.0) == 0.0 ? below : below + 1.0;
        }
        break;
    }
    }
    if (!(rounded >= -9223372036854775808.0 && rounded < 18446744073709551616.0)) {
        return FABER_CONV_RANGE;
    }
    *out = (faber_i128)rounded;
    return *out >= low && *out <= high ? FABER_CONV_OK : FABER_CONV_RANGE;
}

/* `fractus ↦ textus`: the shortest digits that read back, and no `.0` on an
 * integral value (`1.0 ↦ textus` is `1`), as Rust's `Display` writes it. */
static inline faber_text faber_float_display(faber_arena *arena, double value) {
    char buffer[FABER_F64_TEXT];
    const char *shown = faber_f64_text(value, buffer);
    size_t length = strlen(shown);
    if (length >= 2 && shown[length - 2] == '.' && shown[length - 1] == '0') {
        length -= 2;
    }
    return faber_text_make(arena, shown, length, (int64_t)length);
}

#endif /* FABER_H */
